const dayStamp = () => new Date().toISOString().slice(0, 10);
const dayOfYear = () => Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86_400_000);
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

